import{_ as a,o as t,c as o,a3 as s}from"./chunks/framework.DOLRlNb_.js";const u=JSON.parse(`{"title":"The catalog's shape","description":"","frontmatter":{},"headers":[],"relativePath":"docs/the-catalog.md","filePath":"docs/the-catalog.md"}`),n={name:"docs/the-catalog.md"};function i(r,e,d,h,c,l){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="the-catalog-s-shape" tabindex="-1">The catalog&#39;s shape <a class="header-anchor" href="#the-catalog-s-shape" aria-label="Permalink to &quot;The catalog&#39;s shape&quot;">​</a></h1><p>The rules an exercise in the catalog follows, for anyone changing the <code>catalog</code> module or the apps&#39; filters. The terms are in the <a href="./../CONTEXT">glossary</a>; the admin who edits and publishes the catalog is described in <a href="./admin#catalog">the admin area</a>, and phones download it exercise by exercise without an account (<a href="./adr/0030-the-catalog-changes-by-exercise-revision-not-by-catalog-version">ADR 0030</a>, <a href="./adr/0033-the-server-database-is-the-catalog-and-nothing-ships-bundled">ADR 0033</a>).</p><p>A phone that has never downloaded the catalog, such as a first launch with no connection, shows no exercises yet. Tests use a frozen sample (<code>catalog-sample</code>).</p><p>A variation group is the slugs of one movement made easier or harder, ordered from easiest to hardest. An exercise is in at most one group, and a retired one stays in its group but isn&#39;t shown. Every exercise in a group carries a <code>variationNote</code> in every language, the one line the variations sheet shows under its name (&quot;Knees down, a shorter lever&quot;).</p><p>An exercise&#39;s <code>equipment</code> lists what it needs, each need a list of alternatives: <code>[[&quot;DUMBBELL&quot;, &quot;KETTLEBELL&quot;]]</code> is a dumbbell or a kettlebell, <code>[[&quot;DUMBBELL&quot;], [&quot;BENCH&quot;]]</code> is dumbbells and a bench. No need means bodyweight; <code>BODYWEIGHT</code> and <code>MAT</code> are never needs. Equipment that helps but isn&#39;t needed (a mat, a treadmill for a walk) goes in <code>optionalEquipment</code>. The Equipment filter shows an exercise when it uses something ticked, needed or optional, and every need has one alternative ticked; bodyweight-only exercises hide while anything is ticked, unless &quot;No equipment&quot; is.</p><p>An exercise&#39;s optional <code>aliases</code> are other names people search with, per language, which a language may leave out. The search reads them like names but never shows them, and an alias can&#39;t be empty.</p>',6)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
